// src/pages/About.js
import React from "react";
import { Link } from "react-router-dom";

const About = () => {
  return (
    <>
      <style>{`
        .about-page {
          max-width: 1100px;
          margin: 120px auto 60px;
          padding: 0 20px 60px;
          color: #e6e6e6;
          text-align: center;
        }

        .about-header h1 {
          font-size: 42px;
          margin-bottom: 15px;
          background: linear-gradient(to right, #00f2fe, #4facfe);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
        }

        .about-header p {
          max-width: 700px;
          margin: 0 auto 40px;
          font-size: 18px;
          opacity: 0.9;
        }

        .about-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
          gap: 20px;
          margin-top: 30px;
          margin-bottom: 40px;
        }

        .about-card {
          background: rgba(15, 15, 15, 0.9);
          border-radius: 16px;
          padding: 25px 22px;
          border: 1px solid rgba(255, 255, 255, 0.06);
          backdrop-filter: blur(10px);
          transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .about-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 20px rgba(0,255,180,0.3);
        }

        .about-card h2 {
          font-size: 22px;
          margin-bottom: 12px;
          color: #33ff8c;
        }

        .about-card ul {
          list-style: disc;
          padding-left: 18px;
          text-align: left;
        }

        .about-card ul li {
          margin-bottom: 6px;
          font-size: 16px;
        }

        .about-footer h2 {
          font-size: 28px;
          margin-bottom: 15px;
          color: #33ff8c;
        }

        .about-actions {
          display: flex;
          justify-content: center;
          gap: 12px;
          flex-wrap: wrap;
          margin-top: 10px;
        }

        .btn {
          padding: 10px 20px;
          border-radius: 8px;
          font-size: 16px;
          cursor: pointer;
          transition: 0.2s ease;
          text-decoration: none;
        }

        .btn-primary {
          background: #33ff8c;
          color: black;
        }

        .btn-primary:hover {
          background: #22cc6b;
        }

        .btn-secondary {
          background: #444;
          color: white;
        }

        .btn-secondary:hover {
          background: #666;
        }

        /* make floating words ignore clicks */
        .floating-words, .bg-pattern {
          pointer-events: none;
        }
      `}</style>

      <div className="bg-pattern"></div>

      <section className="about-page">
        <div className="about-header fade-in">
          <h1>About CodeGen4Future</h1>
          <p>
            CodeGen4Future is a competitive programming and collaboration
            platform built for students, developers, and teams who want to
            learn, practice, and compete in a modern, real-time environment.
          </p>
        </div>

        <div className="about-grid fade-in">
          <div className="about-card">
            <h2>Our Mission</h2>
            <p>
              To make coding practice, interview preparation, and contests
              accessible to everyone with a fast, intuitive online playground.
            </p>
          </div>

          <div className="about-card">
            <h2>What You Can Do</h2>
            <ul>
              <li>Solve coding problems in an online editor</li>
              <li>Compete in live contests and challenges</li>
              <li>Play 1 vs 1 duels with friends</li>
              <li>Participate in team battles and tournaments</li>
              <li>Track progress via ratings & leaderboards</li>
            </ul>
          </div>

          <div className="about-card">
            <h2>For Students & Placements</h2>
            <p>
              Prepare for coding interviews & exams with practical practice,
              competitive challenges, and analytics-driven improvement.
            </p>
          </div>

          <div className="about-card">
            <h2>For Teams & Communities</h2>
            <p>
              Organize contests & build a strong coding culture within your
              college or tech group.
            </p>
          </div>
        </div>

        <div className="about-footer fade-in">
          <h2>Ready to start?</h2>
          <div className="about-actions">
            <Link to="/problems" className="btn btn-primary">
              Explore Problems
            </Link>
            <Link to="/contests" className="btn btn-secondary">
              Join Contests
            </Link>
            <Link to="/duel" className="btn btn-primary">
              1 vs 1 Duel
            </Link>
          </div>
        </div>
      </section>
    </>
  );
};

export default About;
